#!/usr/bin/env python3
"""
Minimum working example: validate an Olympus result with a real LLM.

Edit the CONFIG block, then:  python example_minimal.py
"""

import json
import os
from pathlib import Path

from app.engine_api import EngineSettings

# ============================================================
#  CONFIG — edit these
# ============================================================

MODEL    = "gemini-2.5-pro"
BASE_URL = "http://localhost:11434/v1"          # Ollama / vLLM / OpenAI
API_KEY  = os.environ.get("GEMINI_API_KEY", "")   # export it; "" for a local server

APK_ROOT  = Path("/media/sf_KaliShared/Shared-Tools/llm-android-analyzer-code-olympus-integration/storage/artifacts/xiaomi-explorer")   # extracted APK job
TEST_PLAN = Path("app/layer4/test_plans/owasp_mastg")
# Reviewer prompt + schema. Generated by tools/build_validation_prompts.py.
SYSTEM_PROMPT = Path("app/layer4/prompts/system/1.system_prompt-validation-v1.md")
SCHEMA        = Path("app/layer4/prompts/system/2.layer3_schema-validation-v1.md")

TEST_ID = "MASTG-TEST-0258"     # broken symmetric cipher modes

