# ============================================================
#  RUN
# ============================================================

# 1. Create the engine. This opens no session yet; it indexes the APK and
#    loads the test plan.
engine = EngineSettings.from_dict({
    "backend": "gemini",
    "model": MODEL,
    "api_key": API_KEY,
    "system_prompt": SYSTEM_PROMPT,
    "schema": SCHEMA,
}).for_apk(APK_ROOT, test_plan_dir=TEST_PLAN)

# 2. Validate. This one call does all of it:
#      - builds an LLM session with the system prompt
#      - registers the 13 code-traversal tools with the model
#        (list_dir, read_file, find_class, find_subclasses, list_imports,
#         grep, search_code, find_callers, find_callees,
#         list_evidence_files, get_evidence_record,
#         match_evidence_records, count_evidence_records)
#      - runs the handshake:  Begin. -> getSchema -> schema -> getPrompt
#      - sends the Olympus output followed by the test prompt
#      - answers the model's evidence requests and tool calls in a loop
#      - parses and stores the verdict
result = engine.validate(TEST_ID, OLYMPUS_OUTPUT)

# 3. Use the answer.
print()
print("Olympus verdict :", OLYMPUS_OUTPUT["verdict"])
print("LLM verdict     :", result.verdict, f"(certainty {result.certainty})")
print("disagreed       :", result.gaps_found)
print("rationale       :", result.rationale)
print("saved to        :", result.output_path)
if result.review_violations:
    print()
    print("!! DO NOT TRUST THIS VERDICT — it contradicts its own rules:")
    for v in result.review_violations:
        print("   -", v)
print()
print(json.dumps(result.full_verdict, indent=2))
